<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/property_v560.php';$me=require_login();pr560_bootstrap_legacy();$flash=!empty($_GET['saved'])?'Property saved successfully.':'';$error='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{csrf_check();$a=(string)($_POST['action']??'');if($a==='save_search'){$name=trim((string)($_POST['name']??''))?:'My Property Search';$filters=$_POST;unset($filters['_csrf'],$filters['action'],$filters['name']);db()->prepare('INSERT INTO property_saved_searches_v560(user_id,name,filters_json,alerts_enabled,created_at,updated_at) VALUES(?,?,?,?,NOW(),NOW())')->execute([(int)$me['id'],$name,pr560_json($filters),!empty($_POST['alerts_enabled'])?1:0]);$flash='Search saved.';}elseif($a==='delete_search'){db()->prepare('DELETE FROM property_saved_searches_v560 WHERE id=? AND user_id=?')->execute([(int)$_POST['search_id'],(int)$me['id']]);$flash='Saved search removed.';}}catch(Throwable $e){$error=$e->getMessage();}}
$listings=pr560_my_listings((int)$me['id']);$favorites=[];foreach(pr560_current_user_favorites((int)$me['id']) as $pid){$x=pr560_listing($pid);if($x)$favorites[]=$x;}$leads=[];$visits=[];$searches=[];try{$q=db()->prepare('SELECT l.*,p.title property_title FROM property_leads_v560 l JOIN city_portal_items p ON p.id=l.property_id LEFT JOIN property_listing_meta_v560 m ON m.portal_item_id=p.id WHERE l.user_id=? OR m.owner_user_id=? OR m.agent_user_id=? ORDER BY l.id DESC LIMIT 100');$q->execute([(int)$me['id'],(int)$me['id'],(int)$me['id']]);$leads=$q->fetchAll()?:[];$q=db()->prepare('SELECT v.*,p.title property_title FROM property_visits_v560 v JOIN city_portal_items p ON p.id=v.property_id LEFT JOIN property_listing_meta_v560 m ON m.portal_item_id=p.id WHERE v.user_id=? OR m.owner_user_id=? OR m.agent_user_id=? ORDER BY v.scheduled_at DESC LIMIT 100');$q->execute([(int)$me['id'],(int)$me['id'],(int)$me['id']]);$visits=$q->fetchAll()?:[];$q=db()->prepare('SELECT * FROM property_saved_searches_v560 WHERE user_id=? ORDER BY id DESC');$q->execute([(int)$me['id']]);$searches=$q->fetchAll()?:[];}catch(Throwable $e){}pr560_public_header('My Property Dashboard','Manage your properties, favorites, inquiries and visits.');?>
<section class="pr560-dashboard"><div class="pr560-shell"><div class="pr560-head"><div><span>MY PROPERTY</span><h2>Property dashboard</h2><p>Welcome <?=e($me['name'])?>. Manage listings, leads, favorites and visits.</p></div><a class="pr560-btn" href="/property-submit.php">＋ Post Property</a></div><?php if($flash):?><div class="pr560-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="pr560-alert err"><?=e($error)?></div><?php endif;?><div class="pr560-dash-grid"><div><span>My Listings</span><b><?=count($listings)?></b><small>Owner / assigned agent</small></div><div><span>Favorites</span><b><?=count($favorites)?></b><small>Saved properties</small></div><div><span>Inquiries</span><b><?=count($leads)?></b><small>Buyer / seller leads</small></div><div><span>Visits</span><b><?=count($visits)?></b><small>Requested / scheduled</small></div></div>
<section class="pr560-panel" style="margin-top:18px"><div class="pr560-head"><div><span>LISTINGS</span><h2 style="font-size:22px">My properties</h2></div></div><div style="overflow:auto"><table class="pr560-table"><thead><tr><th>Property</th><th>Price</th><th>Status</th><th>Views</th><th>Inquiries</th><th></th></tr></thead><tbody><?php foreach($listings as $p):?><tr><td><b><?=e($p['title'])?></b><small style="display:block;color:#718096"><?=e($p['property_type'].' · '.$p['address'])?></small></td><td><?=e(pr560_money((float)$p['price_value'],!empty($p['price_on_call'])))?></td><td><span class="pr560-status <?=e($p['status'])?>"><?=e($p['status'])?></span> <span class="pr560-status <?=e($p['approval_status'])?>"><?=e($p['approval_status'])?></span></td><td><?=number_format((int)$p['views'])?></td><td><?=number_format((int)$p['inquiry_count'])?></td><td><a href="/property-submit.php?id=<?=(int)$p['id']?>">Edit</a> · <a href="/property.php?slug=<?=urlencode($p['slug'])?>">View</a></td></tr><?php endforeach;?><?php if(!$listings):?><tr><td colspan="6">You have not posted a property yet.</td></tr><?php endif;?></tbody></table></div></section>
<section class="pr560-section" style="padding-bottom:0"><div class="pr560-head"><div><span>FAVORITES</span><h2 style="font-size:22px">Saved properties</h2></div></div><div class="pr560-grid"><?php foreach(array_slice($favorites,0,8) as $p)pr560_property_card($p,array_column($favorites,'id'));?><?php if(!$favorites):?><div class="pr560-empty">No favorite properties yet.</div><?php endif;?></div></section>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:28px"><section class="pr560-panel"><h3>Recent inquiries</h3><table class="pr560-table"><tbody><?php foreach(array_slice($leads,0,8) as $l):?><tr><td><b><?=e($l['property_title'])?></b><small style="display:block;color:#718096"><?=e($l['name'].' · '.$l['phone'])?></small></td><td><span class="pr560-status <?=e($l['status'])?>"><?=e($l['status'])?></span></td></tr><?php endforeach;?><?php if(!$leads):?><tr><td>No inquiries yet.</td></tr><?php endif;?></tbody></table></section><section class="pr560-panel"><h3>Property visits</h3><table class="pr560-table"><tbody><?php foreach(array_slice($visits,0,8) as $v):?><tr><td><b><?=e($v['property_title'])?></b><small style="display:block;color:#718096"><?=e(date('d M Y · h:i A',strtotime($v['scheduled_at'])))?></small></td><td><span class="pr560-status <?=e($v['status'])?>"><?=e($v['status'])?></span></td></tr><?php endforeach;?><?php if(!$visits):?><tr><td>No visits scheduled.</td></tr><?php endif;?></tbody></table></section></div>
<section class="pr560-panel" style="margin-top:18px"><h3>Saved searches</h3><form method="post" class="pr560-form" style="grid-template-columns:1.2fr 1fr 1fr auto;align-items:end"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_search"><label>Search name<input name="name" placeholder="5 Marla houses"></label><label>Purpose<select name="purpose"><option value="sale">For Sale</option><option value="rent">For Rent</option></select></label><label>Property type<select name="type"><?php foreach(pr560_types() as $t):?><option><?=e($t)?></option><?php endforeach;?></select></label><button class="pr560-btn">Save search</button></form><div style="margin-top:14px"><?php foreach($searches as $s):?><form method="post" style="display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-top:1px solid #edf1f6"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_search"><input type="hidden" name="search_id" value="<?=(int)$s['id']?>"><span><b><?=e($s['name'])?></b><small style="display:block;color:#718096"><?=e($s['alerts_enabled']?'Alerts enabled':'Saved only')?></small></span><button class="pr560-btn secondary">Remove</button></form><?php endforeach;?></div></section></div></section><?php pr560_public_footer(); ?>
